;/*atelier-chrome*/(function(){
  if (typeof window==="undefined"||typeof document==="undefined") return;
  function boot(){
    if (document.getElementById("site-read-progress")) return;
    var bar=document.createElement("div");
    bar.id="site-read-progress";
    bar.className="site-read-progress";
    bar.setAttribute("aria-hidden","true");
    document.body.appendChild(bar);
    function tick(){
      var max=document.documentElement.scrollHeight-window.innerHeight;
      var p=max>0?Math.min(1,Math.max(0,window.scrollY/max)):0;
      document.documentElement.style.setProperty("--read-progress", String(p));
      document.querySelectorAll(".article-prose .overflow-auto,.markdown .overflow-auto,.article-prose .katex-display").forEach(function(el){
        el.classList.toggle("is-overflowing", el.scrollWidth>el.clientWidth+6);
      });
      var nav=document.querySelector(".site-nav > div");
      if(nav){
        var slide=nav.querySelector(".site-nav-slide");
        if(!slide){
          slide=document.createElement("span");
          slide.className="site-nav-slide";
          slide.setAttribute("aria-hidden","true");
          nav.appendChild(slide);
        }
        var active=nav.querySelector(".site-nav__item--active, a.text-accent");
        if(!active){ slide.style.opacity="0"; }
        else {
          var nb=nav.getBoundingClientRect(), box=active.getBoundingClientRect();
          slide.style.opacity="1";
          slide.style.left="0px";
          slide.style.right="auto";
          slide.style.width=Math.max(14, box.width-22)+"px";
          slide.style.transform="translateX("+(box.left-nb.left+11)+"px)";
        }
      }
    }
    var raf=0;
    var on=function(){ if(raf) return; raf=requestAnimationFrame(function(){ raf=0; tick(); }); };
    window.addEventListener("scroll", on, {passive:true});
    window.addEventListener("resize", on);
    tick();
    setTimeout(tick, 400);
    setTimeout(tick, 1200);
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();
})();
